#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>

int main() {
    const char* results = "Sample results content.";
    char* filename = (char*)malloc(1024 * sizeof(char));
    if (filename == NULL) {
        perror("malloc");
        return 1;
    }

    snprintf(filename, 1024, "/tmp/results_%d_%d.txt", (int)time(NULL), getpid());

    int fd = open(filename, O_WRONLY | O_CREAT | O_EXCL, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("open");
        free(filename);
        return 1;
    }

    ssize_t bytes_written = write(fd, results, strlen(results));
    if (bytes_written == -1 || (size_t)bytes_written != strlen(results)) {
        perror("write");
        close(fd);
        free(filename);
        return 1;
    }

    close(fd);
    printf("File written: %s\n", filename);
    free(filename);
    return 0;
}
